from taf.gnb.oam.coam.vdu.releases.vduoam23r4 import vDuOAM23R4
from taf.gnb.oam.coam.vdu.schemas.agent.get_reset_rannic_operation_response_v1 import (
    GetResetRannicOperationResponseV1,
)
from taf.gnb.oam.coam.vdu.schemas.agent.reset_rannic_response_v1 import (
    ResetRannicResponseV1,
)
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.l1_iq_configuration import (
    M2mLocalL1IqConfigurationResponse,
)
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.l1_iq_data_operation_response import (
    M2mL1IQDataOperationResponseV1,
)
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.script_runner_response import (
    M2MScriptRunnerResponseV1,
)
from taf.gnb.oam.coam.vdu.schemas.fh.get_vswr_band_info import GetVswrBandInfo
from taf.gnb.oam.coam.vdu.schemas.fm_licensed.active_alarms_v2 import (
    ActiveAlarmsLicensedV2,
)
from taf.gnb.oam.coam.vdu.schemas.fm_licensed.historical_alarms_v2 import (
    HistoricalAlarmsLicensedV2,
)
from taf.gnb.oam.coam.vdu.services.bb_config.bb_config_v1 import BBConfigV1
from taf.gnb.oam.coam.vdu.services.fm.fm_v2 import FMv2
from taf.gnb.oam.coam.vdu.services.fm_licensed.fm_licensed_v2 import FMLICENSEDv2
from taf.gnb.oam.coam.vdu.utilities.use_m2m_parser import enforce_use_m2m_type


class vDuOAM24R1(vDuOAM23R4):
    def __init__(self, con_details, need_all_info=False):
        super(vDuOAM24R1, self).__init__(con_details, need_all_info)
        self.bb_config_v1 = BBConfigV1(con_details=self.con_details)
        self.fm_v2 = FMv2(con_details=self.con_details)
        self.fm_licensed_v2 = FMLICENSEDv2(con_details=self.con_details)

    def reset_rannic(self, rannic_r_dn, graceful_cell_shutdown=False, timeout=30, raw=False):
        response = self.bb_config_v1.reset_rannic(rannic_r_dn=rannic_r_dn,
                                                  graceful_cell_shutdown=graceful_cell_shutdown,
                                                  timeout=timeout)
        return response if raw else ResetRannicResponseV1.from_object_dict(response)

    def get_rnic_rest_operation(self, operation_id, timeout=30, raw=False):
        response = self.bb_config_v1.get_rnic_reset_operation(operation_id=operation_id, timeout=timeout)
        return response if raw else GetResetRannicOperationResponseV1.from_object_dict(response)

    def delete_rnic_rest_operation(self, operation_id, timeout=30):
        self.bb_config_v1.delete_rnic_reset_operation(operation_id=operation_id, timeout=timeout)

    def get_vswr_band(self, rmod_dn, ant_port_id, timeout=30):
        response = self.fh_v1.get_vswr_band(rmod_dn=rmod_dn, ant_port_id=ant_port_id, timeout=timeout)
        return list(map(GetVswrBandInfo.from_object_dict, response))

    @enforce_use_m2m_type
    def launch_troubleshooting_script(self, script_name, fixed_param_and_values_list, free_text=None, timeout=30):
        script_runner_res = self.asm_licensed.launch_troubleshooting_script(script_name=script_name,
                                                                            fixed_param_and_values_list=fixed_param_and_values_list,
                                                                            free_text=free_text, timeout=timeout)
        return M2MScriptRunnerResponseV1.from_object_dict(script_runner_res)

    @enforce_use_m2m_type
    def get_script_runner_operation(self, operation_id, timeout=30):
        operation_state = self.asm_licensed.get_script_runner_operation(operation_id=operation_id, timeout=timeout)
        return M2MScriptRunnerResponseV1.from_object_dict(operation_state)

    @enforce_use_m2m_type
    def delete_script_runner_operation(self, operation_id, timeout=30):
        return self.asm_licensed.delete_script_runner_operation(operation_id=operation_id, timeout=timeout)

    @enforce_use_m2m_type
    def collect_l1_iq_data(self, sfn=65535, slot=0, capture_mode='ScheduleSynchronousStopOfOngoingContinuousCapture', timeout=30):
        return self.asm_licensed.collect_l1_iq_data(sfn=sfn, slot=slot, capture_mode=capture_mode, timeout=timeout)

    @enforce_use_m2m_type
    def get_operation_status_of_l1_iq_data_collection(self, operation_id, timeout=30, raw=False):
        response = self.asm_licensed.get_operation_status_of_l1_iq_data_collection(operation_id=operation_id, timeout=timeout)
        return response if raw else M2mL1IQDataOperationResponseV1.from_object_dict(response)

    @enforce_use_m2m_type
    def delete_operation_of_l1_iq_data_collection(self, operation_id, timeout=30):
        self.asm_licensed.delete_operation_of_l1_iq_data_collection(operation_id=operation_id, timeout=timeout)

    @enforce_use_m2m_type
    def get_l1_iq_data_file(self, operation_id, file_id, timeout=30):
        return self.asm_licensed.get_l1_iq_data_file(operation_id=operation_id, file_id=file_id, timeout=timeout)

    @enforce_use_m2m_type
    def get_l1_iq_configuration(self, timeout=30, raw=False):
        response = self.asm_licensed.get_l1_iq_configuration(timeout=timeout)
        return response if raw else M2mLocalL1IqConfigurationResponse.from_object_dict(response)

    @enforce_use_m2m_type
    def activate_l1_iq_data_configuration(self, capture_on_event=False, capture_on_event_from_l1_hi_and_l1_low=False,
                                          dl_nr_subcell_list=None, ul_nr_subcell_list=None, ru_iq_data_parameters_list=None,
                                          capture_frame_offset=None, buffer_cycle=None, reason=None, timeout=30):
        return self.asm_licensed.activate_l1_iq_data_configuration(dl_nr_subcell_list=dl_nr_subcell_list,
                                                                   ul_nr_subcell_list=ul_nr_subcell_list,
                                                                   ru_iq_data_parameters_list=ru_iq_data_parameters_list,
                                                                   capture_frame_offset=capture_frame_offset,
                                                                   capture_on_event=capture_on_event,
                                                                   capture_on_event_from_l1_hi_and_l1_low=capture_on_event_from_l1_hi_and_l1_low,
                                                                   buffer_cycle=buffer_cycle,
                                                                   reason=reason,
                                                                   timeout=timeout)

    @enforce_use_m2m_type
    def get_operation_status_of_activating_l1_iq_data_configuration(self, operation_id, timeout=30, raw=False):
        response = self.asm_licensed.get_operation_status_of_activating_l1_iq_data_configuration(operation_id=operation_id, timeout=timeout)
        return response if raw else M2mL1IQDataOperationResponseV1.from_object_dict(response)

    @enforce_use_m2m_type
    def delete_operation_of_activating_l1_iq_data_configuration(self, operation_id, timeout=30):
        self.asm_licensed.delete_operation_of_activating_l1_iq_data_configuration(operation_id=operation_id, timeout=timeout)

    @enforce_use_m2m_type
    def deactivate_l1_iq_data_configuration(self, timeout=30):
        return self.asm_licensed.deactivate_l1_iq_data_configuration(timeout=timeout)

    @enforce_use_m2m_type
    def get_operation_status_of_deactivating_l1_iq_data_configuration(self, operation_id, timeout=30, raw=False):
        response = self.asm_licensed.get_operation_status_of_deactivating_l1_iq_data_configuration(operation_id=operation_id, timeout=timeout)
        return response if raw else M2mL1IQDataOperationResponseV1.from_object_dict(response)

    @enforce_use_m2m_type
    def delete_operation_of_deactivating_l1_iq_data_configuration(self, operation_id, timeout=30):
        self.asm_licensed.delete_operation_of_deactivating_l1_iq_data_configuration(operation_id=operation_id, timeout=timeout)

    @enforce_use_m2m_type
    def vdu_get_active_alarms(self, timeout=30, use_m2m=True, raw=False, **kwargs):
        if use_m2m:
            active_alarms = self.fm_licensed_v2.vdu_get_active_alarm(timeout=timeout, **kwargs)
        else:
            active_alarms = self.fm_v2.vdu_get_active_alarm(timeout=timeout, **kwargs)

        return active_alarms.to_dict() if raw else ActiveAlarmsLicensedV2.from_object_dict(active_alarms)

    @enforce_use_m2m_type
    def vdu_get_historical_alarms(self, timeout=30, use_m2m=True, raw=False, **kwargs):
        if use_m2m:
            history = self.fm_licensed_v2.vdu_get_historical_alarms(timeout=timeout, **kwargs)
        else:
            history = self.fm_v2.vdu_get_historical_alarms(timeout=timeout, **kwargs)

        return history if raw else HistoricalAlarmsLicensedV2.from_object_dict(history)

    @enforce_use_m2m_type
    def get_troubleshooting_scripts_information(self, owner_module=None, script_name=None, timeout=30):
        return self.asm_licensed.get_troubleshooting_scripts_information(owner_module=owner_module,
                                                                         script_name=script_name,
                                                                         timeout=timeout)
